<article class="vehicle-card"><div class="vehicle-photo"><a href="{{ route('vehicle',$car['id']) }}"><img src="{{ asset('images/'.$car['image']) }}" alt="Illustrative {{ $car['make'] }} vehicle photograph" loading="lazy" width="900" height="600"></a><span class="badge"><i></i> {{ $car['status'] }}</span><button class="favorite" @click="toggleSaved({{ $car['id'] }})" :aria-pressed="saved.includes({{ $car['id'] }})" :class="{'is-saved': saved.includes({{ $car['id'] }})}" aria-label="Save {{ $car['make'] }} {{ $car['model'] }}" x-text="saved.includes({{ $car['id'] }}) ? '♥' : '♡'">♡</button>@if($car['offer'])<span class="offer-badge">SPECIAL OFFER</span>@endif</div><div class="vehicle-body"><p class="vehicle-year">{{ $car['year'] }} <span>· {{ $car['condition'] }}</span></p><h3><a href="{{ route('vehicle',$car['id']) }}">{{ $car['make'] }} {{ $car['model'] }}</a></h3><p class="trim">{{ $car['trim'] }}</p><strong class="price">${{ number_format($car['price']) }}</strong><a class="fee-link" href="{{ route('vehicle',$car['id']) }}#pricing">Price & fee information</a><div class="vehicle-specs"><span>◴ {{ number_format($car['miles']) }} mi</span><span>⚙ {{ $car['transmission'] }}</span><span>◇ {{ $car['fuel'] }}</span></div><label class="compare-check"><input type="checkbox" aria-label="Compare {{ $car['make'] }} {{ $car['model'] }}" :checked="compared.includes({{ $car['id'] }})" @change="toggleCompare({{ $car['id'] }}); $event.target.checked = compared.includes({{ $car['id'] }})"> Compare vehicle</label><a class="details-link" href="{{ route('vehicle',$car['id']) }}">View Details <span>↗</span></a></div></article>


